/* Cargos de la ficha técnica: más de 500, agrupados por departamento y por principales / secundarios.
   Viven en content/roles.json y se cargan la primera vez que se abre una ficha. */
const ROLES = {}, DEPTS = [], ROLE_LEGACY = {};
let rolesState = 0; /* 0 sin cargar · 1 cargando · 2 listo */
function applyRoles(d) {
  if (d && Array.isArray(d.roles) && Array.isArray(d.depts)) {
    DEPTS.length = 0; d.depts.forEach((x, i) => DEPTS.push({ id: x[0], es: x[1], en: x[2], i }));
    const di = {}; DEPTS.forEach((x) => { di[x.id] = x.i; });
    d.roles.forEach((r, o) => { ROLES[r[0]] = { es: r[1], en: r[2], d: r[3], di: di[r[3]] === undefined ? 99 : di[r[3]], main: r[4] === "p", o }; });
    Object.assign(ROLE_LEGACY, d.legacy || {});
  }
  rolesState = 2;
}
function loadRoles() {
  if (rolesState) return; rolesState = 1;
  fetchJSON("roles").then(applyRoles).catch(() => { rolesState = 2; }).then(() => { if (window.__route === "project") render({ keepScroll: true }); });
}

