function hUrl(v, base) { if (/^https?:\/\//i.test(v)) return v; if (/[\s/]/.test(v.replace(/^\/+/, "")) && !/^@/.test(v)) return ""; return base + v.replace(/^@/, "").replace(/^\/+/, ""); }
const contactHref = (c) => { const d = c && CONTACTS[c.k]; const v = c && typeof c.u === "string" ? c.u.trim() : ""; return d && v ? d.u(v) : ""; };


