/* ==========================================================================
   ARTE: logotipos de GORRIóN, carteles, fotogramas y retratos generados en SVG.
   Paleta estricta: negro #000000, blanco #efefef, rojo #5f140f (y mezclas entre ellos para dar profundidad).
   Para usar imágenes reales, añade el campo `poster` (ruta o data: URI) a un proyecto en data.js.
   ========================================================================== */

const INK = "#000000", BONE = "#efefef", RED = "#5f140f";
const MID = "#2f0a07"; // mezcla 50 % negro + rojo, para sombras
let _uid = 0;
const uid = (p) => p + "-" + (++_uid);

function rng(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function hashStr(s) { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

/* ---------- Logotipos (símbolos reutilizables) ---------- */
const LOGO_SPRITE = `<svg width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false">
  <symbol id="logo-h" viewBox="${LOGO_H.vb}"><path fill="currentColor" fill-rule="evenodd" d="${LOGO_H.d}"/></symbol>
  <symbol id="logo-v" viewBox="${LOGO_V.vb}"><path fill="currentColor" fill-rule="evenodd" d="${LOGO_V.d}"/></symbol>
</svg>`;
const logoH = (cls = "", h) => `<svg class="${cls}" viewBox="0 0 ${LOGO_H.w} ${LOGO_H.h}" role="img" aria-label="GORRIóN" ${h ? `height="${h}" width="${Math.round(h * LOGO_H.w / LOGO_H.h)}"` : ""}><use href="#logo-h" width="${LOGO_H.w}" height="${LOGO_H.h}"/></svg>`;
const logoV = (cls = "", h) => `<svg class="${cls}" viewBox="0 0 ${LOGO_V.w} ${LOGO_V.h}" role="img" aria-label="GORRIóN" ${h ? `height="${h}" width="${Math.round(h * LOGO_V.w / LOGO_V.h)}"` : ""}><use href="#logo-v" width="${LOGO_V.w}" height="${LOGO_V.h}"/></svg>`;

/* ---------- Reglas tipográficas de marca ----------
   Como en el nombre GORRIóN: todo en mayúsculas salvo la letra acentuada, que va en minúscula.
   Las palabras de enlace (de, del, y, en, the, of…) se ponen en minúscula cursiva. */
const CONNECT = new Set(["de", "del", "la", "las", "el", "los", "y", "en", "a", "con", "por", "the", "of", "in", "and", "to", "for", "on", "at", "du", "des", "le", "les", "et", "à", "au", "aux", "sur", "dans", "da", "do", "dos", "das", "o", "os", "as", "e", "em", "no", "na", "nos", "nas", "il", "lo", "gli", "di", "della", "dei", "delle", "al", "alla", "nel", "nella", "per", "und", "der", "die", "das", "dem", "den", "von", "aus", "mit", "für", "zu", "am", "im", "auf", "an"]);
const ACC_RE = /[áéíóúüñàâäçèêëîïôöûùãõœæÁÉÍÓÚÜÑÀÂÄÇÈÊËÎÏÔÖÛÙÃÕ]/g;
function brandWords(title) {
  return title.split(/\s+/).filter(Boolean).map((w, i) => {
    const core = w.replace(/[.,:;!?¿¡"“”]/g, "").toLowerCase();
    if (i > 0 && CONNECT.has(core)) return { t: w.toLowerCase(), it: true };
    return { t: w.toUpperCase().replace(ACC_RE, (c) => c.toLowerCase()), it: false };
  });
}
function brandifyDOM(root) {
  root.querySelectorAll("h1, h2, h3, h4").forEach((h) => {
    let first = true;
    const w = document.createTreeWalker(h, NodeFilter.SHOW_TEXT), nodes = [];
    while (w.nextNode()) nodes.push(w.currentNode);
    nodes.forEach((n) => {
      if (n.parentElement && n.parentElement.closest(".lc")) { first = false; return; }
      const parts = n.nodeValue.split(/(\s+)/);
      let changed = false;
      const html = parts.map((tok) => {
        if (!tok || /^\s+$/.test(tok)) return esc(tok);
        const core = tok.replace(/[.,:;!?¿¡"“”]/g, "").toLowerCase();
        let out;
        if (!first && CONNECT.has(core)) { changed = true; out = `<i class="lc">${esc(tok)}</i>`; }
        else out = esc(tok).replace(ACC_RE, (c) => { changed = true; return `<span class="lc">${c.toLowerCase()}</span>`; });
        first = false; return out;
      }).join("");
      if (changed) { const s = document.createElement("span"); s.innerHTML = html; n.replaceWith(...s.childNodes); }
    });
  });
}

