/* Cabeceras de página: primeros planos (recortes) del gorrión del hero y del segundo gorrión, con animaciones simples. */
function headArt(seed = 0) {
  const v = Math.abs(seed | 0) % 3;
  let fence = "";
  for (let i = -2; i < 12; i++) fence += `<path d="M${i * 70} 90V340" stroke="#000" stroke-opacity=".5" stroke-width="3"/>`;
  let holes = "";
  for (let i = 0; i < 10; i++) holes += `<rect x="${18 + i * 40}" y="10" width="14" height="14" fill="#efefef" fill-opacity=".55"/><rect x="${18 + i * 40}" y="376" width="14" height="14" fill="#efefef" fill-opacity=".55"/>`;
  const g = `ph${v}`;
  const bg = `<rect width="400" height="400" fill="#000"/><polygon points="90,0 260,0 400,180 400,330 0,330 0,110" fill="url(#${g}r)"/><g class="bd-fence"><g>${fence}<path d="M0 200H1200" stroke="#000" stroke-opacity=".5" stroke-width="3"/></g></g><rect y="330" width="400" height="70" fill="#1c1c1c"/>`;
  let art;
  if (v === 0) art = `<g transform="scale(.95) translate(-150 -196)"><g transform="translate(1080 0) scale(-1 1)">${birdPaths("bd-body")}</g></g>`;
  else if (v === 1) art = `<g transform="translate(46 4) scale(.36) translate(-190 -20)">${bird2Paths()}</g>`;
  else art = `<g transform="scale(.8) translate(-470 -210)">${birdPaths("bd-body")}</g>`;
  return `<svg viewBox="0 0 400 400" aria-hidden="true"><defs><linearGradient id="${g}r" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#000"/><stop offset=".35" stop-color="${MID}"/><stop offset=".75" stop-color="${RED}"/><stop offset="1" stop-color="#7d1c12"/></linearGradient><clipPath id="${g}c"><rect width="400" height="400"/></clipPath></defs>
  <g clip-path="url(#${g}c)">${bg}${art}</g><rect x="1" y="1" width="398" height="398" fill="none" stroke="#efefef" stroke-opacity=".35" stroke-width="2"/>${holes}</svg>`;
}

/* ---------- Carteles generados 2:3 ---------- */
function posterLines(title, maxChars) {
  const words = brandWords(title), lines = [[]];
  words.forEach((w) => {
    const cur = lines[lines.length - 1], len = cur.reduce((a, x) => a + x.t.length + 1, 0) + w.t.length;
    if (!cur.length || len <= maxChars) cur.push(w); else lines.push([w]);
  });
  return lines.slice(0, 4);
}
/* Imágenes subidas desde el panel (/uploads/xxx.webp): en cada publicación se generan versiones pequeñas
   (uploads/w480, w800, w1200) y aquí se ofrecen con srcset para que el móvil descargue solo lo que necesita.
   Si una versión no existe todavía, la imagen vuelve sola a la original. */
const IMG_W = [480, 800, 1200];
function imgAttrs(src, sizes) {
  const m = /^\/?uploads\/([^/?#]+\.webp)$/i.exec(String(src || ""));
  if (!m || !PATHMODE) return `src="${esc(src)}"`;
  const set = IMG_W.map((w) => `${BASE}uploads/w${w}/${m[1]} ${w}w`).join(", ") + `, ${BASE}uploads/${m[1]} 1800w`;
  return `src="${esc(src)}" srcset="${esc(set)}" sizes="${esc(sizes)}" onerror="this.onerror=null;this.removeAttribute('srcset');this.removeAttribute('sizes')"`;
}
function posterSVG(p, lang) {
  if (p.poster) return `<img ${imgAttrs(p.poster, "(max-width: 700px) 90vw, 520px")} alt="${esc(p.title)}" loading="lazy" style="width:100%;height:100%;object-fit:cover">`;
  const R = rng(p.seed * 97 + hashStr(p.slug) % 1000), g = uid("pg");
  const lines = posterLines(p.title, 10);
  const longest = Math.max(...lines.map((l) => l.reduce((a, x) => a + x.t.length + 1, -1)));
  const fs = Math.min(76, Math.floor(330 / (longest * 0.66)));
  const lh = fs * 0.92, yEnd = 518, yStart = yEnd - (lines.length - 1) * lh;
  let art = "";
  const sx = 120 + R() * 160;
  switch (p.style) {
    case "rays": {
      let ray = "";
      for (let i = 0; i < 70; i++) { const a = (i / 70) * Math.PI * 2; ray += `<line x1="${sx.toFixed(0)}" y1="230" x2="${(sx + Math.cos(a) * 480).toFixed(0)}" y2="${(230 + Math.sin(a) * 480).toFixed(0)}" stroke="${BONE}" stroke-opacity="${i % 2 ? .06 : .2}"/>`; }
      art = `${ray}<circle cx="${sx.toFixed(0)}" cy="230" r="110" fill="${RED}"/><circle cx="${sx.toFixed(0)}" cy="230" r="110" fill="none" stroke="${BONE}" stroke-width="2"/><polygon points="0,330 400,250 400,600 0,600" fill="${INK}"/><line x1="0" y1="330" x2="400" y2="250" stroke="${BONE}"/>`;
      break;
    }
    case "diamond":
      art = `<polygon points="${sx.toFixed(0)},40 ${(sx + 190).toFixed(0)},230 ${sx.toFixed(0)},420 ${(sx - 190).toFixed(0)},230" fill="${RED}"/><polygon points="${sx.toFixed(0)},40 ${(sx + 190).toFixed(0)},230 ${sx.toFixed(0)},230" fill="${MID}"/><polygon points="${(sx + 20).toFixed(0)},70 ${(sx + 200).toFixed(0)},250 ${(sx + 20).toFixed(0)},430 ${(sx - 160).toFixed(0)},250" fill="none" stroke="${BONE}" stroke-width="2"/><line x1="0" y1="${(100 + R() * 80).toFixed(0)}" x2="400" y2="${(300 + R() * 80).toFixed(0)}" stroke="${BONE}" stroke-opacity=".8"/>`;
      break;
    case "stripes": {
      let s = "";
      for (let i = 0; i < 6; i++) { const x = -120 + i * 80 + R() * 30, w = 20 + R() * 50; s += `<polygon points="${(x + 220).toFixed(0)},0 ${(x + 220 + w).toFixed(0)},0 ${(x + w).toFixed(0)},470 ${x.toFixed(0)},470" fill="${i % 3 === 1 ? BONE : i % 2 ? RED : MID}" fill-opacity="${i % 3 === 1 ? ".9" : "1"}"/>`; }
      art = `${s}<circle cx="${(290 - R() * 60).toFixed(0)}" cy="${(120 + R() * 60).toFixed(0)}" r="34" fill="${BONE}"/>`;
      break;
    }
    case "circle":
      art = `<circle cx="${sx.toFixed(0)}" cy="250" r="140" fill="${BONE}"/><rect x="0" y="250" width="400" height="${(60 + R() * 40).toFixed(0)}" fill="${RED}"/><rect x="0" y="${(330 + R() * 20).toFixed(0)}" width="400" height="8" fill="${INK}"/><circle cx="${sx.toFixed(0)}" cy="250" r="154" fill="none" stroke="${BONE}" stroke-opacity=".5" stroke-dasharray="2 12" stroke-width="8"/>`;
      break;
    default:
      art = `<polygon points="0,110 ${(230 + R() * 100).toFixed(0)},430 0,430" fill="${RED}"/><polygon points="0,110 ${(230 + R() * 100).toFixed(0)},430 380,300 0,60" fill="${MID}" opacity=".8"/><polygon points="400,0 400,200 250,0" fill="${BONE}"/><line x1="0" y1="${(200 + R() * 60).toFixed(0)}" x2="400" y2="${(380 + R() * 60).toFixed(0)}" stroke="${BONE}"/>`;
  }
  const tl = L(TYPES[p.type]);
  const tspans = lines.map((l, i) => `<text x="28" y="${(yStart + i * lh).toFixed(0)}" font-size="${fs}" fill="${BONE}" style="font-family:var(--f-display);font-weight:500;letter-spacing:.01em">${l.map((w, j) => (j ? " " : "") + (w.it ? `<tspan font-style="italic">${esc(w.t)}</tspan>` : esc(w.t))).join("")}</text>`).join("");
  let holes = ""; for (let i = 0; i < 13; i++) holes += `<rect x="${14 + i * 30}" y="578" width="10" height="10" fill="${BONE}" fill-opacity=".55"/>`;
  return `<svg viewBox="0 0 400 600" preserveAspectRatio="xMidYMid slice" role="img" aria-label="${esc(p.title)}">
  <defs><linearGradient id="${g}f" x1="0" y1="0" x2="0" y2="1"><stop offset=".5" stop-color="${INK}" stop-opacity="0"/><stop offset=".82" stop-color="${INK}" stop-opacity=".95"/></linearGradient></defs>
  <rect width="400" height="600" fill="${INK}"/>${art}
  <rect width="400" height="600" fill="url(#${g}f)"/>
  <use href="#logo-h" x="26" y="22" width="86" height="39.4" color="${BONE}"/>
  ${tspans}
  <rect x="28" y="${yEnd + 16}" width="44" height="4" fill="${BONE}"/>
  <text x="28" y="${yEnd + 42}" font-size="12" fill="${BONE}" fill-opacity=".9" style="font-family:var(--f-body);font-weight:700;letter-spacing:.2em">${esc(tl.toUpperCase())} · ${p.year}</text>
  ${holes}</svg>`;
}

/* ---------- Fotogramas 2.39:1 (de ejemplo) ---------- */
function stillSVG(seed, idx) {
  const R = rng(seed * 31 + idx * 17 + 5), g = uid("sg");
  const hz = 100 + R() * 40;
  let far = "", near = "", x = 0;
  while (x < 478) { const w = 14 + R() * 38, h = 20 + R() * 54; far += `<rect x="${x.toFixed(0)}" y="${(hz - h).toFixed(0)}" width="${w.toFixed(0)}" height="${h.toFixed(0)}" fill="${MID}"/>`; x += w + R() * 6; }
  x = -10;
  while (x < 478) { const w = 30 + R() * 70, h = 26 + R() * 60, y = 200 - h; near += `<rect x="${x.toFixed(0)}" y="${y.toFixed(0)}" width="${w.toFixed(0)}" height="${h.toFixed(0)}" fill="${INK}"/>`; if (R() > .5) near += `<rect x="${(x + w * .3).toFixed(0)}" y="${(y - 14).toFixed(0)}" width="${(w * .3).toFixed(0)}" height="14" fill="${INK}"/>`; x += w + R() * 4; }
  const sunX = 60 + R() * 360, mode = idx % 3;
  const sun = mode === 1 ? `<circle cx="${sunX.toFixed(0)}" cy="${(hz - 22).toFixed(0)}" r="${(24 + R() * 20).toFixed(0)}" fill="${BONE}"/>` : `<circle cx="${sunX.toFixed(0)}" cy="${(hz - 10).toFixed(0)}" r="${(30 + R() * 26).toFixed(0)}" fill="${mode === 2 ? BONE : RED}" ${mode === 2 ? 'fill-opacity=".85"' : ""}/>`;
  let stars = "";
  for (let i = 0; i < 9; i++) stars += `<circle cx="${(R() * 478).toFixed(0)}" cy="${(R() * 60).toFixed(0)}" r="${(R() * 1.2 + .4).toFixed(1)}" fill="${BONE}" fill-opacity=".7"/>`;
  return `<svg viewBox="0 0 478 200" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="${g}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${mode === 1 ? INK : MID}"/><stop offset=".62" stop-color="${mode === 1 ? MID : RED}"/><stop offset="1" stop-color="${INK}"/></linearGradient></defs>
  <rect width="478" height="200" fill="url(#${g})"/>${stars}${sun}${far}${near}
  <line x1="0" y1="${(30 + R() * 40).toFixed(0)}" x2="478" y2="${(40 + R() * 40).toFixed(0)}" stroke="${BONE}" stroke-opacity=".3"/></svg>`;
}

/* ---------- Retratos geométricos (de ejemplo) ---------- */
function avatarSVG(name, seed) {
  const R = rng(seed * 13 + 7), ini = name.split(" ").map((w) => w[0]).slice(0, 2).join("");
  const bgs = [RED, INK, BONE, MID], bg = bgs[seed % 4], fg = bg === BONE ? INK : BONE, alt = bg === RED || bg === MID ? INK : RED;
  const sh = [];
  sh.push(`<polygon points="0,200 ${(60 + R() * 80).toFixed(0)},${(40 + R() * 40).toFixed(0)} 200,${(100 + R() * 60).toFixed(0)} 200,200" fill="${alt}"/>`);
  sh.push(`<circle cx="${(40 + R() * 120).toFixed(0)}" cy="${(40 + R() * 40).toFixed(0)}" r="${(16 + R() * 20).toFixed(0)}" fill="${fg}"/>`);
  sh.push(`<line x1="0" y1="${(R() * 200).toFixed(0)}" x2="200" y2="${(R() * 200).toFixed(0)}" stroke="${fg}" stroke-opacity=".5"/>`);
  return `<svg viewBox="0 0 200 200" role="img" aria-label="${esc(name)}"><rect width="200" height="200" fill="${bg}"/>${sh.join("")}<text x="14" y="184" font-size="62" fill="${fg}" style="font-family:var(--f-display);font-weight:500">${esc(ini)}</text></svg>`;
}

