/* ==========================================================================
   EFECTOS DE SCROLL "ESCRIBIENDO UN GUION"
   - El texto de títulos y párrafos se escribe letra a letra según se baja y se borra al subir
     (scrub: el progreso depende de la posición, no del tiempo). Un cursor parpadea donde se escribe.
   - Entre secciones aparecen rótulos de escena (ESC. INT./EXT.) y transiciones (CORTE A:), como en un guion.
   - Tarjetas y bloques entran con un fundido y un "telón" que depende del sentido del scroll.
   - Contador de página (PÁG. n/N) y barra de progreso.
   Todo lo que está en la primera pantalla se muestra completo al cargar. Se desactiva con
   prefers-reduced-motion y con el modo ligero.
   ========================================================================== */
const FX = (() => {
  const mq = window.matchMedia ? window.matchMedia("(prefers-reduced-motion: reduce)") : { matches: false };
  const SLUGS = {
    es: ["INT. SALA DE PROYECCIÓN — NOCHE", "EXT. AZOTEA — ATARDECER", "INT. CUARTO DE MONTAJE — MADRUGADA", "EXT. MALECÓN — AMANECER", "INT. ESTUDIO — DÍA", "EXT. LA CUADRA — TARDE"],
    en: ["INT. SCREENING ROOM — NIGHT", "EXT. ROOFTOP — DUSK", "INT. EDITING ROOM — EARLY MORNING", "EXT. MALECÓN — DAWN", "INT. STUDIO — DAY", "EXT. THE BLOCK — AFTERNOON"],
  };
  const CUT = { es: "CORTE A:", en: "CUT TO:" };
  const OUT = { es: "FUNDIDO A NEGRO.", en: "FADE OUT." };
  const PG = { es: "PÁG.", en: "PAGE" };
  const TEXT_SEL = "main h1, main h2, main .lede, main .hero__sub, main .tagline, main .prose p, main .quote, .scene .slug, .scene .cut";
  const RV_SEL = ".card, .nitem, .svc__i, .values > div, .step, .person, .laurel, .where, .tl, .still, .kit__i, .press a, .press .pr";
  let items = [], activeItems = new Set(), itemByElement = new WeakMap(), io = null, ioText = null, enabled = false, ticking = false, lastY = 0, cursorEl = null, pager = null, bound = false, lastFrameAt = 0, frameTimer = 0;
  const COARSE = () => !!(window.matchMedia && (window.matchMedia("(pointer: coarse)").matches || window.matchMedia("(max-width: 900px)").matches));
  const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
  const html = document.documentElement;

  function split(el) {
    const text = el.textContent, chars = [];
    const walk = (node) => {
      Array.from(node.childNodes).forEach((n) => {
        if (n.nodeType === 3) {
          const frag = document.createDocumentFragment();
          n.nodeValue.split(/(\s+)/).forEach((tok) => {
            if (!tok) return;
            if (/^\s+$/.test(tok)) { frag.appendChild(document.createTextNode(tok)); return; }
            const w = document.createElement("span");
            w.className = "w"; w.setAttribute("aria-hidden", "true");
            if (COARSE()) { w.classList.add("ch"); w.textContent = tok; chars.push(w); } /* móvil: palabra a palabra (6× menos nodos) */
            else Array.from(tok).forEach((c) => { const s = document.createElement("span"); s.className = "ch"; s.textContent = c; w.appendChild(s); chars.push(s); });
            frag.appendChild(w);
          });
          n.replaceWith(frag);
        } else if (n.nodeType === 1) walk(n);
      });
    };
    walk(el);
    const sr = document.createElement("span"); sr.className = "sr"; sr.textContent = text; el.prepend(sr);
    return chars;
  }

  function addScenes(root) {
    const L = SLUGS[lang] ? lang : "en";
    const secs = Array.from(root.querySelectorAll("main > section")).filter((s) => !s.classList.contains("hero") && !s.classList.contains("dock"));
    secs.forEach((s, i) => {
      const w = s.querySelector(":scope > .wrap"); if (!w) return;
      const d = document.createElement("div");
      d.className = "wrap scene"; d.setAttribute("aria-hidden", "true");
      d.innerHTML = `<span class="slug">${i + 1}. ${esc(SLUGS[L][i % SLUGS[L].length])}</span><span class="cut">${CUT[L]}</span>`;
      s.insertBefore(d, w);
    });
    const foot = root.querySelector(".foot");
    if (foot && foot.firstElementChild) {
      const d = document.createElement("div");
      d.className = "wrap scene scene--out"; d.setAttribute("aria-hidden", "true");
      d.innerHTML = `<span class="cut">${OUT[L]}</span>`;
      foot.insertBefore(d, foot.firstElementChild);
    }
  }

  /* Posiciones en caché: en cada scroll NO se lee el layout (evita recalcular estilos y trabarse en móviles) */
  let docH = 1, topEl = null, vhC = 0;
  function measure() {
    const sy = window.scrollY;
    vhC = window.innerHeight; docH = html.scrollHeight;
    for (const it of items) { const r = it.el.getBoundingClientRect(); it.top = r.top + sy; it.h = r.height; }
  }
  function onResize() { if (!enabled) return; measure(); onScroll(); }
  let lastProg = -1, lastPage = "";
  function frame() {
    ticking = false;
    lastFrameAt = performance.now();
    const y = window.scrollY, vh = vhC || window.innerHeight;
    const dy = y - lastY;
    if (Math.abs(dy) > 1) { const d = dy > 0 ? "down" : "up"; if (html.dataset.dir !== d) html.dataset.dir = d; lastY = y; }
    const max = Math.max(1, docH - vh);
    const prog = clamp(y / max, 0, 1).toFixed(3);
    if (prog !== lastProg) {
      lastProg = prog;
      if (!topEl || !topEl.isConnected) topEl = document.querySelector(".top");
      if (topEl) topEl.style.setProperty("--prog", prog);
      if (pager) pager.style.setProperty("--prog", prog);
    }
    if (pager) {
      const total = Math.max(1, Math.ceil(docH / vh)), page = clamp(Math.floor((y + vh * 0.5) / vh) + 1, 1, total);
      const txt = `${PG[PG[lang] ? lang : "en"]} ${String(page).padStart(2, "0")}/${String(total).padStart(2, "0")}`;
      if (txt !== lastPage) { lastPage = txt; pager.firstChild.textContent = txt; }
    }
    let cur = null;
    for (const it of activeItems) {
      const top = it.top - y, bottom = top + it.h;
      let p;
      if (top > vh * 1.1) p = 0;
      else if (bottom < -vh * 0.1) p = 1;
      else p = clamp((vh * 0.9 - top) / (Math.min(it.h, vh * 0.45) + vh * 0.14), 0, 1);
      const n = Math.round(p * it.chars.length);
      if (n !== it.n) {
        const a = Math.min(n, it.n), b = Math.max(n, it.n), on = n > it.n;
        for (let i = a; i < b; i++) it.chars[i].classList.toggle("on", on);
        it.n = n;
      }
      if (n > 0 && top < vh * 0.95 && bottom > 0 && (!cur || it.index > cur.index)) cur = it;
    }
    const ce = cur ? cur.chars[cur.n - 1] : null;
    if (ce !== cursorEl) { if (cursorEl) cursorEl.classList.remove("cur"); if (ce) ce.classList.add("cur"); cursorEl = ce; }
  }
  let scrollPauseTimer = 0;
  function onScroll() {
    if (!enabled) return;
    if (COARSE()) {
      html.classList.add("scrolling");
      clearTimeout(scrollPauseTimer);
      scrollPauseTimer = setTimeout(() => html.classList.remove("scrolling"), 120);
    }
    if (ticking) return;
    ticking = true;
    const delay = COARSE() ? Math.max(0, 32 - (performance.now() - lastFrameAt)) : 0;
    if (delay) frameTimer = setTimeout(() => { frameTimer = 0; requestAnimationFrame(frame); }, delay);
    else requestAnimationFrame(frame);
  }

  function init(root) {
    if (io) { io.disconnect(); io = null; }
    if (ioText) { ioText.disconnect(); ioText = null; }
    clearTimeout(frameTimer); clearTimeout(scrollPauseTimer);
    frameTimer = 0; scrollPauseTimer = 0; ticking = false;
    items = []; activeItems.clear(); itemByElement = new WeakMap(); cursorEl = null;
    enabled = !lite && !mq.matches && "IntersectionObserver" in window;
    html.classList.toggle("fx", enabled);
    html.classList.remove("scrolling");
    if (!bound) {
      bound = true;
      window.addEventListener("scroll", onScroll, { passive: true });
      window.addEventListener("resize", onResize);
      window.addEventListener("load", onResize);
      if (document.fonts && document.fonts.ready) document.fonts.ready.then(onResize);
    }
    if (!enabled) { if (pager) pager.hidden = true; return; }
    if (!pager) {
      pager = document.createElement("div"); pager.className = "pager"; pager.setAttribute("aria-hidden", "true");
      pager.innerHTML = "<span></span><i><b></b></i>"; document.body.appendChild(pager);
    }
    pager.hidden = false;
    addScenes(root);
    const vh = window.innerHeight, sy = window.scrollY;
    const docTop = (el) => el.getBoundingClientRect().top + sy;

    /* Texto: solo se escribe lo que queda debajo de la primera pantalla */
    root.querySelectorAll(TEXT_SEL).forEach((el) => {
      if (el.closest(".card, .nitem, .notice, .sdlg")) return;
      if (docTop(el) < vh * 0.9) return;
      const chars = split(el);
      if (chars.length) {
        const item = { el, chars, n: 0, index: items.length };
        items.push(item);
        itemByElement.set(el, item);
      }
    });
    ioText = new IntersectionObserver((entries) => {
      let changed = false;
      entries.forEach((entry) => {
        const item = itemByElement.get(entry.target);
        if (!item) return;
        if (entry.isIntersecting) {
          if (!activeItems.has(item)) { activeItems.add(item); changed = true; }
        } else if (activeItems.delete(item)) changed = true;
      });
      if (changed) onScroll();
    }, { rootMargin: `${Math.ceil(vh * 1.3)}px 0px` });
    items.forEach((item) => ioText.observe(item.el));

    /* Bloques: fundido y telón según el sentido del scroll */
    io = new IntersectionObserver((es) => es.forEach((e) => e.target.classList.toggle("in", e.isIntersecting)), { rootMargin: "0px 0px -6% 0px", threshold: 0.06 });
    root.querySelectorAll(RV_SEL).forEach((el) => {
      if (docTop(el) < vh * 0.9) return;
      const sibs = Array.from(el.parentElement.children).filter((c) => c.matches(RV_SEL));
      el.style.setProperty("--i", String(Math.max(0, sibs.indexOf(el)) % 4));
      el.classList.add("rv");
      io.observe(el);
    });
    measure();
    setTimeout(onResize, 600);
    frame();
  }
  /* Pausa las animaciones infinitas de los SVG cuando no se ven */
  let ioA = null;
  function watchAnim(root) {
    if (!("IntersectionObserver" in window)) return;
    if (ioA) ioA.disconnect();
    ioA = new IntersectionObserver((es) => es.forEach((e) => e.target.classList.toggle("anim-off", !e.isIntersecting)), { rootMargin: "80px" });
    root.querySelectorAll(".hero__art, .page-head__art, .fh__bg, .buddy").forEach((el) => ioA.observe(el));
  }
  return { init, watchAnim, measure: onResize };
})();

/* ==========================================================================
   GORRIÓN COMPAÑERO
   - Hero: el gorrión sigue el scroll con retardo (lerp), se inclina y se encoge un poco.
   - Al llegar al final de la página vuela a la esquina inferior derecha, se hace pequeño y
     "habla" en un globo de texto con la acción de contacto. Al subir de nuevo, se va.
   ========================================================================== */
const Buddy = (() => {
  let el = null, bound = false, on = false, dismissed = false, s = 0, target = 0, raf = 0, tIn = 0, tOut = 0;
  let hero = null, art = null, heroTop = 0, heroHeight = 0;
  const html = document.documentElement;
  const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

  function build() {
    el = document.createElement("aside");
    el.className = "buddy"; el.id = "buddy";
    document.body.appendChild(el);
    el.addEventListener("click", (e) => {
      if (e.target.closest("[data-buddy-x]")) { talk(false); return; }
      const b = e.target.closest(".buddy__bird");
      if (b) { b.classList.remove("hop"); void b.offsetWidth; b.classList.add("hop"); talk(true); }
    });
  }
  /* El globo habla un rato y se desvanece; un clic en el gorrión lo vuelve a sacar. */
  function talk(v, delay) {
    clearTimeout(tIn); clearTimeout(tOut);
    const go = () => {
      el.classList.toggle("talk", v);
      if (v) tOut = setTimeout(() => el.classList.remove("talk"), 5200);
    };
    if (v && delay) tIn = setTimeout(go, delay); else go();
  }
  function fill() {
    el.innerHTML = `<div class="buddy__bubble" role="group" aria-label="${esc(t("buddy_t"))}"><button class="buddy__x" type="button" data-buddy-x aria-label="${esc(t("buddy_x"))}">×</button><p>${esc(t("buddy_t"))}</p><a class="btn btn--red" href="${routeHref("contacto")}">${esc(t("buddy_b"))} ${ICONS.arrow}</a></div><button class="buddy__bird" type="button" aria-label="${esc(t("buddy_t"))}">${buddyBird()}</button>`;
  }
  function setOn(v) {
    if (v === on) return;
    on = v; el.classList.toggle("on", v); html.classList.toggle("buddy-on", v);
    if (v) { el.removeAttribute("inert"); talk(true, 1000); } else { el.setAttribute("inert", ""); talk(false); }
  }
  function measureHero() {
    hero = document.querySelector(".hero");
    art = hero && hero.querySelector(".hero__art svg");
    if (!hero) { heroTop = 0; heroHeight = 0; return; }
    const rect = hero.getBoundingClientRect();
    heroTop = rect.top + window.scrollY;
    heroHeight = rect.height;
  }
  function tick() {
    raf = 0;
    s += (target - s) * 0.07;
    if (art) {
      art.style.setProperty("--by", (s * 110).toFixed(1) + "px");
      art.style.setProperty("--br", (s * -6).toFixed(2) + "deg");
      art.style.setProperty("--bsc", (1 - s * 0.14).toFixed(3));
      art.classList.toggle("is-moving", Math.abs(target - s) > 0.002);
    }
    if (Math.abs(target - s) > 0.002) raf = requestAnimationFrame(tick);
  }
  function onScroll() {
    const vh = window.innerHeight, y = window.scrollY;
    /* Inicio: el gorrión vuela a la esquina al terminar el hero. Resto de páginas: ya está en la esquina, sin vuelo. */
    const past = hero ? y >= heroTop + heroHeight - vh * 0.3 : true;
    if (el.classList.contains("static") !== !hero) el.classList.toggle("static", !hero);
    setOn(past && window.__route !== "contacto");
    const nextTarget = hero ? clamp(y / Math.max(1, heroHeight), 0, 1) : 0;
    if (nextTarget !== target) {
      target = nextTarget;
      if (!raf && Math.abs(target - s) > 0.002) raf = requestAnimationFrame(tick);
    }
  }
  function sync() {
    if (!el) build();
    fill();
    measureHero();
    if (!bound) {
      bound = true;
      window.addEventListener("scroll", onScroll, { passive: true });
      window.addEventListener("resize", () => { measureHero(); onScroll(); }, { passive: true });
      if (document.fonts && document.fonts.ready) document.fonts.ready.then(measureHero);
    }
    on = !on; setOn(!on); // fuerza estado coherente tras re-render
    s = 0; target = 0;
    if (art) { art.style.removeProperty("--by"); art.style.removeProperty("--br"); art.style.removeProperty("--bsc"); art.classList.remove("is-moving"); }
    onScroll();
  }
  return { sync };
})();
